"""Representative editorial judgments: first sixteen complex-number pathways."""
NOTES={
 'angle-units':('Convert familiar degrees.','Correct the conversion factor.','Convert signed multiple turns.','Combine rotations across units.','Enumerate integer turns within a half-open interval.','Mixed-unit congruences and half-angle restrictions; enrichment.'),
 'argand-coordinates':('Read ordered coordinates.','Correct axis interchange.','Plot a quadrant-II point.','Reflect in each axis and both.','Recover an endpoint from midpoint.','Classify a moving point across quadrant and axis boundaries; diagrams still needed.'),
 'argand-displacement':('Interpret directed movement.','Distinguish endpoint from displacement.','Compute oriented sum and difference.','Construct parallelogram and diagonals; linked geometry.','Recover endpoints from both diagonals.','Classify degeneracy and perpendicularity using Cartesian coordinates.'),
 'argument-normalization':('Convert complete turns.','Correct excluded negative-pi endpoint.','Normalize signed angle.','Normalize successive product and quotient angles.','Recover both possible original arguments.','Classify piecewise wrapping with correct endpoint conventions.'),
 'argument-range':('Argument on positive axis.','Correct arctangent quadrant.','Use quadrant-II exact angle.','Use directed displacement and alternate range.','Recover exact point on a ray from its real component.','Revised AD: varying signs, origin exclusion and inverse angle constraints.'),
 'argument-rays':('Read imaginary-axis angle.','Distinguish translated ray and line.','Write ray as Cartesian condition.','Intersect two rays and check directions.','Intersect ray and circle; reject opposite direction.','Classify all ray-circle intersections including tangency and excluded endpoint.'),
 'cartesian-product':('Reduce powers of i.','Correct sign of imaginary product.','Expand two factors.','Revised AD: solve a ray condition and check direction.','Invert a fixed complex product and prove uniqueness.','Add a compatibility constraint to product inversion; retain, monitor overlap with division.'),
 'cartesian-sums':('Signed arithmetic.','Correct subtraction of imaginary component.','Compute sum and difference.','Invert nested subtraction.','Solve coupled complex sums.','Revised AG: reconstruct ordered pairs from sum, equal moduli and separation; distinguish zero and impossible distance.'),
 'cartesian-to-polar':('Find distance from origin.','Correct quadrant of inverse tangent.','Convert exact quadrant-III point.','Revised AG: convert two directed displacements in different quadrants.','Recover missing signed component from modulus.','Classify all arguments from a fixed modulus and moving real component.'),
 'complex-discriminant':('Calculate discriminant.','Contrast equal middle coefficients with different discriminants.','Classify nonmonic quadratic without solving.','Determine interval for nonreal roots.','Compare two quadratics and repeated boundaries.','Classify two moving discriminants and their common zero.'),
 'complex-division':('Multiply conjugates.','Explain rationalization.','Divide two complex numbers.','Verify quotient modulus independently.','Recover imaginary component from real quotient condition.','Revised AD: two-parameter quotient with singular and excluded-denominator cases.'),
 'complex-quadratic':('Solve negative square.','Recover omitted conjugate.','Apply formula to nonmonic quadratic.','Complete square after translation and verify symmetric data.','Infer coefficient from imaginary magnitude.','Classify real and complex roots, moduli and signs.'),
 'complex-regions':('Intersect elementary inequalities.','Reject excluded circular boundary.','Sketch two half-plane conditions.','Find half-disk area and distinguish boundary types.','Intersect circle and bisector; select closer side.','Moving strict half-plane and disk supremum; enrichment.'),
 'conjugate-deduction':('Reflect a point.','Identify real-coefficient hypothesis by counterexample.','Deduce third root.','Use conjugate multiplicity to bound degree.','Recover remaining root from coefficient.','Construct minimum degree polynomial for coincident or distinct forced roots.'),
 'conjugate-factor':('Multiply numerical conjugates.','Correct constant sign.','Construct monic real quadratic factor.','Recover scale from polynomial value.','Construct factor then divide quartic.','Classify quadratics from value and imaginary magnitude; weaker than T5 computation but inverse classification; further review queued.'),
 'conjugate-find':('Reflect Cartesian point.','Distinguish conjugate and negation.','Expand before conjugating.','Solve real-coefficient conjugate equation.','Solve imaginary-coefficient conjugate equation.','Classify singular and regular conjugate equations; monitor structural overlap with other systems.'),
}
def scope(path,tier):
    if path not in NOTES or tier not in range(1,7): raise ValueError('Not reviewed in FM-16AG')
    if tier==6 and path in ('angle-units','complex-regions'): return 'enrichment_only'
    return {1:'prerequisite_bridge_reviewed',2:'conceptual_diagnostic_reviewed',3:'syllabus_linked_candidate',4:'syllabus_linked_candidate',5:'syllabus_linked_candidate',6:'challenge_candidate'}[tier]
